package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import com.creatorhub.model.Student; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.servlet.*; import java.io.*; @WebServlet("/profile") public class ProfileServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!ok(r)){s.sendRedirect(r.getContextPath()+"/?error=Login+required");return;}try{r.setAttribute("student",new CreatorDAO().student((Integer)r.getSession().getAttribute("studentId")));r.getRequestDispatcher("/WEB-INF/jsp/profile.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{Student x=new Student();x.setStudentId((Integer)r.getSession().getAttribute("studentId"));x.setRoleTitle(r.getParameter("roleTitle"));x.setAboutMe(r.getParameter("aboutMe"));x.setSkills(r.getParameter("skills"));x.setWorkText(r.getParameter("workText"));new CreatorDAO().updateProfile(x);s.sendRedirect(r.getContextPath()+"/profile?message=Profile+updated");}catch(Exception e){throw new IOException(e);}}private boolean ok(HttpServletRequest r){return r.getSession(false)!=null&&r.getSession(false).getAttribute("studentId")!=null;}}
